function analyticsMetricRefreshButton(key){return '<button class="analyticsMetricRefresh" type="button" onclick="analyticsRefreshMetric(&quot;'+key+'&quot;)">'+(S.analyticsMetricRefreshing===key?'Updating':'Update')+'</button>'}
function analyticsMetricSpark(rows){const now=Date.now();const buckets=[0,0,0,0,0,0,0,0];rows.forEach(function(e){const age=Math.floor((now-(Date.parse(e.createdAt||0)||now))/86400000);if(age>=0&&age<8)buckets[7-age]++});const max=Math.max(1,...buckets);return '<div class="analyticsMetricSpark" aria-hidden="true">'+buckets.map(function(value,index){const height=Math.max(12,Math.round(value/max*100));return '<i style="height:'+height+'%" data-index="'+index+'"></i>'}).join('')+'</div>'}
function analyticsMetricTrayHeader(open){return '<div class="analyticsMetricsTrayHeader"><div><p>Key signals</p><span>'+(open?'Live performance counters with eight-day movement.':'Performance counters are collapsed.')+'</span></div><button type="button" onclick="analyticsToggleMetricsTray()">'+(open?'Hide metrics':'Show metrics')+'</button></div>'}
function analyticsMetricTray(cards){const open=analyticsMetricsOpen();return '<section class="analyticsMetricsTrayMenu">'+analyticsMetricTrayHeader(open)+(open?'<div class="analyticsMetricsTray">'+cards+'</div>':'')+'</section>'}
function analyticsMetricShell(key,title,value,note,controls,rows){return '<section class="analyticsMetricCard analyticsMetricCard-'+key+'"><div class="analyticsMetricCardTop"><div><p>'+esc(title)+'</p><b>'+esc(value)+'</b><span>'+esc(note)+'</span></div><div class="analyticsMetricControls">'+(controls||'')+analyticsMetricRefreshButton(key)+'</div></div>'+analyticsMetricSpark(rows||[])+'</section>'}
function analyticsUniqueSessionsMetric(){const rows=analyticsMetricEventsFor('unique');const sessions=new Set(rows.map(function(e){return e.sessionId||''}).filter(Boolean));return analyticsMetricShell('unique','Unique sessions',sessions.size,analyticsMetricRangeLabel(analyticsMetricRange('unique')),analyticsMetricRangeSelect('unique'),rows)}
