function analyticsModernStats(items){return '<div class="analyticsModernStats">'+items.map(function(item){return analyticsModernStat(item[0],item[1],item[2])}).join('')+'</div>'}
function analyticsModernRows(title,map,limit,caption){const entries=analyticsModernEntries(map,limit);const max=Math.max(1,...entries.map(function(item){return item[1]}));const rows=entries.length?entries.map(function(item){const pct=Math.max(5,Math.round(item[1]/max*100));return '<div class="analyticsModernRow"><div><b>'+esc(item[0])+'</b><span>'+esc(caption||'Tracked activity')+'</span></div><strong>'+esc(item[1])+'</strong><i><em style="width:'+pct+'%"></em></i></div>'}).join(''):'<div class="analyticsModernEmpty">No data captured yet.</div>';return analyticsModernCard(title,caption||'Ranked by captured activity.',rows,entries.length+' rows')}
function analyticsModernSignal(title,value,note){return '<div class="analyticsModernSignal"><span>'+esc(title)+'</span><b>'+esc(value)+'</b><p>'+esc(note||'')+'</p></div>'}
