function analyticsModernRecentEvents(events,limit){const recent=[...events].sort(function(a,b){return analyticsTime(b)-analyticsTime(a)}).slice(0,limit||10);if(!recent.length)return '<div class="analyticsModernEmpty">No events in this window.</div>';return '<div class="analyticsModernStream">'+recent.map(function(e){return '<div class="analyticsModernEvent"><span></span><div><b>'+esc(e.type||'event')+'</b><p>'+esc(analyticsPath(e.sourceUrl))+' - '+esc(analyticsModernReferrer(e))+'</p></div><strong>'+esc((e.createdAt||'').slice(5,16).replace('T',' '))+'</strong></div>'}).join('')+'</div>'}
