function analyticsModernDonut(title,subtitle,map,centerLabel){const entries=analyticsModernEntries(map,6);const total=Math.max(0,entries.reduce(function(sum,item){return sum+item[1]},0));const colors=['#7357ff','#00c2ff','#ff5d8f','#ffb020','#20c997','#3f8cff'];let cursor=0;const stops=entries.map(function(item,index){const start=cursor;cursor+=total?item[1]/total*100:0;return colors[index%colors.length]+' '+start+'% '+cursor+'%'});const gradient=stops.length?'conic-gradient('+stops.join(',')+')':'#e9eef8';const legend=entries.length?entries.map(function(item,index){const pct=total?Math.round(item[1]/total*100):0;return '<div class="analyticsDonutLegendRow"><i style="background:'+colors[index%colors.length]+'"></i><span>'+esc(item[0])+'</span><b>'+pct+'%</b></div>'}).join(''):'<div class="analyticsModernEmpty">No distribution yet.</div>';return analyticsModernCard(title,subtitle,'<div class="analyticsDonutSystem"><div class="analyticsDonutGraphic" style="background:'+gradient+'"><div><b>'+total+'</b><span>'+esc(centerLabel||'events')+'</span></div></div><div class="analyticsDonutLegend">'+legend+'</div></div>','Distribution')}
function analyticsModernFunnel(events){const views=events.filter(function(e){return e.type==='page_view'}).length;const interactions=events.filter(function(e){return e.type!=='page_view'}).length;const forms=events.filter(function(e){return e.type==='form_submission'}).length;const max=Math.max(1,views,interactions,forms);const stages=[['Page views',views,'Traffic entering tracked pages'],['Interactions',interactions,'Actions beyond a page load'],['Form submits',forms,'High-intent conversion events']];return analyticsModernCard('Conversion path','A visual path from attention to intent.','<div class="analyticsFunnelSystem">'+stages.map(function(stage){const width=Math.max(18,Math.round(stage[1]/max*100));return '<div class="analyticsFunnelStage"><div><span>'+esc(stage[0])+'</span><b>'+stage[1]+'</b></div><p>'+esc(stage[2])+'</p><i style="--funnel-width:'+width+'%"><em></em></i></div>'}).join('')+'</div>',views?(Math.round(forms/views*100)+'% conversion'):'Waiting for views')}
