function analyticsOverviewToggleExpand(key){const closing=analyticsOverviewExpanded(key);S.analyticsOverviewExpanded=closing?'':key;document.body.classList.toggle('analyticsOverviewModalOpen',!closing);render();requestAnimationFrame(function(){const control=document.querySelector('[data-overview-block="'+key+'"] .analyticsOverviewExpand');if(control)control.focus()})}
