function analyticsOverviewBlock(key,title,subtitle,body,details,tools,badge,className){const expanded=analyticsOverviewExpanded(key);const titleId='analyticsOverviewTitle-'+key;return '<section class="analyticsOverviewBlock analyticsModernCard '+(className||'')+' '+(expanded?'is-expanded':'')+'" data-overview-block="'+key+'" role="'+(expanded?'dialog':'region')+'" '+(expanded?'aria-modal="true" ':'')+'aria-labelledby="'+titleId+'"><div class="analyticsOverviewBlockHead"><div class="analyticsOverviewBlockTitle"><span>'+esc(badge||'Overview')+'</span><h3 id="'+titleId+'">'+esc(title)+'</h3><p>'+esc(subtitle||'')+'</p></div><div class="analyticsOverviewBlockActions">'+(tools||'')+'<button class="analyticsOverviewExpand '+(expanded?'is-collapse':'')+'" type="button" aria-expanded="'+expanded+'" aria-label="'+(expanded?'Collapse expanded ':'Expand ')+esc(title)+'" onclick="analyticsOverviewToggleExpand(&quot;'+key+'&quot;)">'+(expanded?'Collapse view':'Expand')+' <span aria-hidden="true">'+(expanded?'&times;':'+')+'</span></button></div></div><div class="analyticsOverviewBlockBody"><div class="analyticsOverviewCompactVisual">'+body+'</div>'+(expanded?'<div class="analyticsOverviewExpandedData"><div class="analyticsOverviewExpandedHead"><b>Full data</b><span>Values shown for '+esc(analyticsRangeLabel().toLowerCase())+'.</span></div>'+details+'</div>':'')+'</div></section>'}
function analyticsOverviewPreviousEvents(){const rows=analyticsPreviousEvents();const type=analyticsEventFilter();return type==='all'?rows:rows.filter(function(e){return (e.type||'unknown')===type})}
function analyticsOverviewMetricValue(events,metric){if(metric==='sessions')return new Set(events.map(function(e){return e.sessionId||''}).filter(Boolean)).size;if(metric==='views')return events.filter(function(e){return e.type==='page_view'}).length;if(metric==='forms')return events.filter(function(e){return e.type==='form_submission'}).length;return events.length}
