function analyticsOverviewMetricButtons(){const current=S.analyticsOverviewMetric||'events';return '<div class="analyticsOverviewSwitch" aria-label="Trend metric">'+[['events','Events'],['sessions','Sessions'],['views','Page views'],['forms','Forms']].map(function(item){return '<button type="button" aria-pressed="'+(current===item[0])+'" onclick="analyticsOverviewSet(&quot;analyticsOverviewMetric&quot;,&quot;'+item[0]+'&quot;)">'+esc(item[1])+'</button>'}).join('')+'</div>'}
function analyticsOverviewBuckets(events,metric){const range=analyticsRangeDays();const end=Date.now();const sourceTimes=events.map(analyticsTime).filter(Boolean);const start=range>=99999?(sourceTimes.length?Math.min(...sourceTimes):end-13*86400000):end-range*86400000;const span=Math.max(3600000,end-start);const count=range===1?12:14;const size=span/count;const buckets=Array.from({length:count},function(_,index){const from=start+index*size;const to=index===count-1?end+1:from+size;const date=new Date(from);return {from:from,to:to,label:range===1?String(date.getHours()).padStart(2,'0')+':00':(date.getMonth()+1)+'/'+date.getDate(),events:[]}});events.forEach(function(event){const time=analyticsTime(event);let index=Math.floor((time-start)/size);if(index<0||index>=count)return;buckets[index].events.push(event)});return buckets.map(function(bucket){return {label:bucket.label,value:analyticsOverviewMetricValue(bucket.events,metric)}})}
function analyticsOverviewTrend(events,previous){const metric=S.analyticsOverviewMetric||'events';const buckets=analyticsOverviewBuckets(events,metric);const values=buckets.map(function(bucket){return bucket.value});const max=Math.max(1,...values);const left=20,right=740,top=22,bottom=190;const step=(right-left)/Math.max(1,buckets.length-1);const points=buckets.map(function(bucket,index){return {x:left+index*step,y:bottom-(bucket.value/max)*(bottom-top),value:bucket.value,label:bucket.label}});const line=points.map(function(point,index){return (index?'L':'M')+point.x.toFixed(1)+' '+point.y.toFixed(1)}).join(' ');const area=line+' L '+right+' '+bottom+' L '+left+' '+bottom+' Z';const current=analyticsOverviewMetricValue(events,metric);const prior=analyticsOverviewMetricValue(previous,metric);const delta=analyticsPct(current,prior);const deltaClass=analyticsDeltaClass(current,prior);const labels=points.map(function(point,index){if(index%3!==0&&index!==points.length-1)return '';return '<text x="'+point.x.toFixed(1)+'" y="226" text-anchor="'+(index===0?'start':index===points.length-1?'end':'middle')+'">'+esc(point.label)+'</text>'}).join('');const dots=points.map(function(point){return '<g><circle cx="'+point.x.toFixed(1)+'" cy="'+point.y.toFixed(1)+'" r="5"><title>'+esc(point.label+': '+point.value+' '+analyticsOverviewMetricLabel(metric).toLowerCase())+'</title></circle></g>'}).join('');const chart='<div class="analyticsOverviewTrendSummary"><b>'+current+'</b><span class="'+deltaClass+'">'+(analyticsRangeDays()>=99999?'All-time total':delta+' vs previous period')+'</span></div><div class="analyticsOverviewChartWrap"><svg viewBox="0 0 760 246" role="img" aria-label="'+esc(analyticsOverviewMetricLabel(metric)+' trend with '+current+' total')+'"><defs><linearGradient id="analyticsOverviewArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".34"></stop><stop offset="100%" stop-color="currentColor" stop-opacity=".02"></stop></linearGradient></defs><line x1="'+left+'" y1="64" x2="'+right+'" y2="64"></line><line x1="'+left+'" y1="127" x2="'+right+'" y2="127"></line><line x1="'+left+'" y1="'+bottom+'" x2="'+right+'" y2="'+bottom+'"></line><path class="analyticsOverviewArea" d="'+area+'"></path><path class="analyticsOverviewLine" d="'+line+'"></path>'+dots+labels+'</svg></div>';const details='<div class="analyticsOverviewDetailSummary"><div><span>Current</span><b>'+current+'</b></div><div><span>Previous</span><b>'+prior+'</b></div><div><span>Change</span><b>'+delta+'</b></div></div>'+analyticsOverviewTable(['Period',analyticsOverviewMetricLabel(metric)],buckets.map(function(bucket){return [bucket.label,bucket.value]}));return analyticsOverviewBlock('trend',analyticsOverviewMetricLabel(metric)+' over time','Movement across the selected analytics window.',chart,details,analyticsOverviewMetricButtons(),'Momentum','analyticsOverviewTrend analyticsOverviewBlockWide metric-'+metric)}
function analyticsOverviewInsight(label,current,previous,note){const delta=analyticsPct(current,previous);const direction=analyticsDeltaClass(current,previous);const amount=Math.min(100,Math.max(8,Math.abs(Math.round((current-previous)/Math.max(previous,1)*100))));return '<div class="analyticsOverviewInsight '+direction+'"><i></i><div><span>'+esc(label)+'</span><b>'+esc(analyticsRangeDays()>=99999?current:delta)+'</b><p>'+esc(note)+'</p><em><strong style="--delta-width:'+amount+'%"></strong></em></div></div>'}
